struct BatchDetail:View{
    @Bindable var store:AppStore;let batch:Batch
    @State private var action:StockAction?
    @Environment(\.dismiss) private var dismiss
    var lot:Batch{store.workspace?.lots.first{$0.id==batch.id} ?? batch}
    var body:some View{ScrollView{if let w=store.workspace{VStack(alignment:.leading,spacing:24){VStack(alignment:.leading,spacing:12){Text(w.name(lot)).font(.title.bold());Text(lot.batch).font(.body).foregroundStyle(YF.muted);StatusBadge(status:lot.quality);Text("\(kg(w.grams(lot.id))) kg").font(.largeTitle.bold()).monospacedDigit()}.panel()
        VStack(alignment:.leading,spacing:20){SectionTitle(title:"Stock stages");ForEach(stages,id:\.self){stage in FactRow(stageName(stage),"\(kg(w.grams(lot.id,stage:stage))) kg").font(.body)};Divider();FactRow("Supplier",lot.supplier.isEmpty ? "Not recorded" : lot.supplier).font(.body)}.panel()
        VStack(spacing:12){Button{action = .receive}label:{Label("Receive stock",systemImage:"arrow.down.left")}.buttonStyle(YFButton());Button{action = .transfer}label:{Label("Move between stages",systemImage:"arrow.left.arrow.right")}.buttonStyle(YFButton(primary:false));Button{action = .dispatch}label:{Label("Dispatch stock",systemImage:"truck.box")}.buttonStyle(YFButton(primary:false)).disabled(lot.quality != "approved");if lot.quality != "approved"{Text("Owner QC approval is required before dispatch.").font(.body).foregroundStyle(YF.muted)};Button{action = .inspection}label:{Label("Record inspection",systemImage:"doc.text.viewfinder")}.buttonStyle(YFButton(primary:false));if store.isOwner{Button{action = .quality}label:{Label("Review batch quality",systemImage:"checkmark.shield")}.buttonStyle(YFButton(primary:false))};Button{action = .waste}label:{Label("Record waste",systemImage:"arrow.down.bin")}.buttonStyle(YFButton(primary:false))}
        VStack(alignment:.leading,spacing:18){SectionTitle(title:"Inspection notes");let notes=w.inspections.filter{$0.lotId==lot.id};if notes.isEmpty{Text("No inspection notes yet. Record the label and physical checks before approving.").font(.body).foregroundStyle(YF.muted)};ForEach(notes){note in VStack(alignment:.leading,spacing:10){Text(note.note).font(.body);if !note.labelText.isEmpty{Text("Label: \(note.labelText)").font(.body)};Text("\(note.actorName) · \(recordDate(note.createdAt))").font(.subheadline).foregroundStyle(YF.muted)};Divider()}}.panel()
        VStack(alignment:.leading,spacing:18){SectionTitle(title:"Quality history");ForEach(w.qualityEvents.filter{$0.lotId==lot.id}){event in VStack(alignment:.leading,spacing:10){StatusBadge(status:event.status);Text(event.note).font(.body);Text(recordDate(event.createdAt)).font(.subheadline).foregroundStyle(YF.muted)}};if !w.qualityEvents.contains(where:{$0.lotId==lot.id}){Text("No decisions recorded yet.").font(.body).foregroundStyle(YF.muted)}}.panel()
    }.padding(20)}}.background(YF.canvas).navigationTitle("Batch details").navigationBarTitleDisplayMode(.inline).toolbar{ToolbarItem(placement:.topBarTrailing){Button("Done"){dismiss()}.frame(minHeight:44)}}.sheet(item:$action){value in ActionForm(store:store,action:value,lotId:lot.id)}}
}
struct ActionForm:View{
    @Bindable var store:AppStore;let action:StockAction
    @State private var draft:Draft
    @State private var reviewing=false
    @State private var saving=false
    @State private var error=""
    @Environment(\.dismiss) private var dismiss
    init(store:AppStore,action:StockAction,lotId:String?=nil){self.store=store;self.action=action;var initial=Draft();initial.productId=store.workspace?.products.first?.id ?? "";initial.lotId=lotId ?? store.workspace?.lots.first?.id ?? "";_draft=State(initialValue:initial)}
    var body:some View{NavigationStack{Form{if let w=store.workspace{
        Section{Label(store.review ? "Review mode · sample stock only" : "Connected workspace · server confirmation required",systemImage:"checkmark.shield").font(.subheadline).foregroundStyle(YF.muted)}
        if reviewing{Section("Review before saving"){FactRow("Action",action.title);if action == .material{FactRow("Material",draft.name);FactRow("SKU",draft.sku)}else if action == .batch{FactRow("Material",w.products.first{$0.id==draft.productId}?.name ?? "Not selected");FactRow("Batch",draft.batch);FactRow("Supplier",draft.supplier)}else{FactRow("Batch",w.batchName(draft.lotId));if action == .quality{FactRow("QC decision",qualityName(draft.quality))}else if action == .inspection{FactRow("Label",draft.label.isEmpty ? "Not recorded" : draft.label)}else{FactRow("Weight","\(draft.amount) kg");FactRow("Stage",stageName(draft.stage));if action == .transfer{FactRow("Destination",stageName(draft.toStage))}};if !draft.note.isEmpty{FactRow("Notes",draft.note)}}}.font(.body)}
        else{Section(action.title){if action == .material{field("Material name",text:$draft.name);field("SKU",text:$draft.sku)}else if action == .batch{Picker("Material",selection:$draft.productId){ForEach(w.products){p in Text(p.name).tag(p.id)}};field("Batch / dye lot",text:$draft.batch);field("Supplier",text:$draft.supplier)}else{
            Picker("Batch",selection:$draft.lotId){ForEach(w.lots){lot in Text("\(lot.batch) · \(w.name(lot))").tag(lot.id)}}
            if action == .quality{Picker("Quality decision",selection:$draft.quality){Text("Approve after inspection").tag("approved");Text("Hold for review").tag("hold");Text("Needs inspection").tag("uninspected")};Text("Owner approval requires a physical check and a recorded reason.").font(.body).foregroundStyle(YF.muted)}else if action == .inspection{field("Care-label text",text:$draft.label);Text("Manual evidence does not create an AI prediction or automatically release a hold.").font(.body).foregroundStyle(YF.muted)}else{Picker("Stock stage",selection:$draft.stage){ForEach(stages,id:\.self){Text(stageName($0)).tag($0)}};if action == .transfer{Picker("Destination",selection:$draft.toStage){ForEach(stages,id:\.self){Text(stageName($0)).tag($0)}}};field("Weight in kg",text:$draft.amount,keyboard:.decimalPad);Text("Available in this stage: \(kg(w.grams(draft.lotId,stage:draft.stage))) kg").font(.body).foregroundStyle(YF.muted)}
            VStack(alignment:.leading,spacing:10){Text(action == .quality ? "Physical inspection reason" : "Notes").font(.body.weight(.medium));TextField("Record what the next operator should know",text:$draft.note,axis:.vertical).lineLimit(3...6).font(.body)}.padding(.vertical,5)
        }}}
        if !error.isEmpty{Section{Label(error,systemImage:"exclamationmark.triangle").font(.body).foregroundStyle(.red).accessibilityAddTraits(.updatesFrequently)}}
        Section{Button{if !reviewing{reviewing=true;return};saving=true;Task{do{try await store.save(action,draft:draft);dismiss()}catch{self.error=error.localizedDescription};saving=false}}label:{HStack{if saving{ProgressView()};Text(saving ? "Saving…" : reviewing ? "Confirm and save" : "Review entry")}}.buttonStyle(YFButton()).disabled(saving);if reviewing{Button("Edit entry"){reviewing=false;error=""}.frame(minHeight:44).font(.body)};Text("Original movements remain in the activity history. Corrections use a recorded reversal.").font(.body).foregroundStyle(YF.muted)}
    }}.navigationTitle(action.title).navigationBarTitleDisplayMode(.inline).toolbar{ToolbarItem(placement:.topBarLeading){Button("Cancel"){dismiss()}.disabled(saving).frame(minHeight:44)}}.interactiveDismissDisabled(saving)}}
    func field(_ title:String,text:Binding<String>,keyboard:UIKeyboardType = .default)->some View{VStack(alignment:.leading,spacing:10){Text(title).font(.body.weight(.medium));TextField(title,text:text).font(.body).keyboardType(keyboard).textInputAutocapitalization(.never).autocorrectionDisabled().accessibilityLabel(title)}.padding(.vertical,8)}
}
struct SettingsView:View{
