    var body:some View{VStack(alignment:.leading,spacing:24){VStack(alignment:.leading,spacing:20){SectionTitle(title:"Make yourself at home.",subtitle:"Preferences for your workspace and device.");Picker("Appearance",selection:$store.theme){Text("Light").tag("light");Text("Dark").tag("dark");Text("Follow system").tag("system")}.font(.body).frame(minHeight:44).onChange(of:store.theme){_,v in UserDefaults.standard.set(v,forKey:"yf-theme")};Text("Text follows your iPhone’s Dynamic Type setting. Buttons keep at least a 44-point touch area.").font(.body).foregroundStyle(YF.muted)}.panel()
        VStack(alignment:.leading,spacing:16){SectionTitle(title:"Connections");Text("Inventory server").font(.body.weight(.medium));TextField("Inventory URL",text:$store.server).keyboardType(.URL).textInputAutocapitalization(.never).autocorrectionDisabled().textFieldStyle(.roundedBorder).font(.body);Text("TexPilot model server").font(.body.weight(.medium));TextField("Model URL",text:$store.modelServer).keyboardType(.URL).textInputAutocapitalization(.never).autocorrectionDisabled().textFieldStyle(.roundedBorder).font(.body);Button{UserDefaults.standard.set(store.server,forKey:"yf-server");UserDefaults.standard.set(store.modelServer,forKey:"yf-model");store.notice="Connection preferences saved on this device."}label:{Text("Save connection preferences")}.buttonStyle(YFButton(primary:false));Text("Changing this address does not authenticate a hosted account. Native hosted authentication needs its own deployment configuration.").font(.body).foregroundStyle(YF.muted)}.panel()
        VStack(alignment:.leading,spacing:18){SectionTitle(title:"Your workspace");FactRow("Mode",store.review ? "Design review" : "Connected");FactRow("Time zone","Asia/Karachi");FactRow("Your role",store.isOwner ? "Owner" : "Operator");Button{store.signOut()}label:{Label("Sign out",systemImage:"rectangle.portrait.and.arrow.right")}.buttonStyle(YFButton(primary:false))}.panel()}}
}
struct NativeScanner:View{
