        if mode == "Fabric"{VStack(alignment:.leading,spacing:20){ZStack{RoundedRectangle(cornerRadius:14).fill(YF.canvas);if let photo,let image=UIImage(data:photo){Image(uiImage:image).resizable().scaledToFit().padding(16).accessibilityLabel("Selected inspection photo")}else{VStack(spacing:16){Image(systemName:"viewfinder").font(.largeTitle).foregroundStyle(YF.action);Text("Keep the fabric flat and well-lit.").font(.body).foregroundStyle(YF.muted).multilineTextAlignment(.center).padding(.horizontal,20)}}}.frame(height:240)
            PhotosPicker(selection:$selectedPhoto,matching:.images){Label(photo==nil ? "Choose inspection photo" : "Replace inspection photo",systemImage:"photo")}.buttonStyle(YFButton(primary:false)).onChange(of:selectedPhoto){_,item in Task{do{photo=try await item?.loadTransferable(type:Data.self);result="";error=""}catch{self.error="This photo could not be opened. Choose another image."}}}
            Button{camera=true}label:{Label("Take a photo",systemImage:"camera")}.buttonStyle(YFButton(primary:false)).disabled(!UIImagePickerController.isSourceTypeAvailable(.camera));if !UIImagePickerController.isSourceTypeAvailable(.camera){Text("The simulator has no camera. Choose a photo to review this flow.").font(.subheadline).foregroundStyle(YF.muted)}
            VStack(alignment:.leading,spacing:10){Text("Care-label text").font(.body.weight(.medium));TextField("e.g. 100% COTTON",text:$label,axis:.vertical).lineLimit(3...6).font(.body).padding(14).background(YF.canvas,in:RoundedRectangle(cornerRadius:10))}
            Button{Task{await analyse()}}label:{HStack{if working{ProgressView()};Label(store.review ? "Preview sample result" : "Inspect material",systemImage:"viewfinder")}}.buttonStyle(YFButton()).disabled(working || (!store.review && (photo==nil || !modelReady)));Text("Exact fibre composition comes from the label. An ordinary photo does not prove fibre percentages.").font(.body).foregroundStyle(YF.muted)
        }.panel();if !result.isEmpty{VStack(alignment:.leading,spacing:14){Label(result.hasPrefix("PASS") ? "Consistent" : result.hasPrefix("FLAG") ? "Needs review" : "Insufficient evidence",systemImage:"checkmark.shield").font(.title3.bold());if let outcome { HStack { ScannerOutcomeArtwork(group:"Verification",label:outcome["verdict"] as? String);Text("Verification outcome").font(.headline) };ForEach(["structure","fibre_family","treatment","garment"],id:\.self){key in let head=outcome[key] as? [String:Any];HStack{ScannerOutcomeArtwork(group:["structure":"Fabric","fibre_family":"Fibre family","treatment":"Treatment","garment":"Garment"][key]!,label:head?["label"] as? String);VStack(alignment:.leading,spacing:6){Text(key.replacingOccurrences(of:"_",with:" ").capitalized).font(.headline);Text(head?["label"] as? String ?? "Insufficient evidence").font(.body).foregroundStyle(YF.muted)}}}};Text(result).font(.body).foregroundStyle(YF.muted);Text("This evidence does not automatically approve a batch.").font(.body).foregroundStyle(YF.muted)}.panel()}}
        else{VStack(alignment:.leading,spacing:20){SectionTitle(title:"Find a batch by its label",subtitle:"Enter the Yarnflow QR code value, material barcode, or batch number.");TextField("Barcode or batch number",text:$code).font(.body).textInputAutocapitalization(.never).autocorrectionDisabled().padding(14).background(YF.canvas,in:RoundedRectangle(cornerRadius:10));Button{Task{await lookup()}}label:{Label("Find batch",systemImage:"magnifyingglass")}.buttonStyle(YFButton()).disabled(code.trimmingCharacters(in:.whitespaces).isEmpty||working)}.panel()}
        if !error.isEmpty{Label(error,systemImage:"exclamationmark.triangle").font(.body).foregroundStyle(.red).panel()}
    }.task(id:store.modelServer){_ = await checkModel()}.sheet(item:$found){lot in NavigationStack{BatchDetail(store:store,batch:lot)}}.sheet(isPresented:$camera){CameraCapture(data:$photo)}}
    func checkModel() async -> Bool {
        modelReady=false
        guard let url=URL(string:store.modelServer.trimmingCharacters(in:.init(charactersIn:"/"))+"/api/v1/model"),url.scheme=="https" || (["localhost","127.0.0.1"].contains(url.host ?? "") && url.scheme=="http") else { modelStatus="Use HTTPS, or localhost for development.";return false }
