        catch {modelStatus="Model unavailable · check the model server in Settings.";return false}
    }
    func lookup() async{working=true;error="";defer{working=false};if store.review{found=store.workspace?.lots.first{$0.batch.caseInsensitiveCompare(code) == .orderedSame || "YF:\($0.id)"==code};if found==nil{error="No matching sample batch. Try LOT-1024."};return};do{let data=try await store.request("/lookup?code="+(code.addingPercentEncoding(withAllowedCharacters:.urlQueryAllowed) ?? code));let object=try JSONSerialization.jsonObject(with:data) as? [String:Any];if let id=object?["lotId"] as? String{found=store.workspace?.lots.first{$0.id==id}}else{error="This product has several batches. Find the printed batch in Inventory."}}catch{self.error=error.localizedDescription}}
    func analyse() async{working=true;error="";result="";defer{working=false};if store.review{try? await Task.sleep(for:.milliseconds(650));outcome=["verdict":"INSUFFICIENT_EVIDENCE"];result="INSUFFICIENT_EVIDENCE · Illustrative result. This sample cannot support a reliable verdict. Capture clearer surface and label evidence.";return};guard await checkModel() else{error="The trained model is not connected. Start it and retry.";return};guard let photo,let image=UIImage(data:photo),let jpeg=image.jpegData(compressionQuality:0.86),let url=URL(string:store.modelServer.trimmingCharacters(in:.init(charactersIn:"/"))+"/api/v1/scan"),url.scheme=="https" || ["localhost","127.0.0.1"].contains(url.host ?? "") else{error="Choose a supported photo and a valid HTTPS model server, or localhost for development.";return}
        let boundary="Yarnflow-\(UUID().uuidString)";var body=Data();func append(_ value:String){body.append(Data(value.utf8))};append("--\(boundary)\r\nContent-Disposition: form-data; name=\"surface_image\"; filename=\"surface.jpg\"\r\nContent-Type: image/jpeg\r\n\r\n");body.append(jpeg);append("\r\n--\(boundary)\r\nContent-Disposition: form-data; name=\"label_text\"\r\n\r\n\(label)\r\n--\(boundary)--\r\n");var request=URLRequest(url:url);request.httpMethod="POST";request.timeoutInterval=90;request.setValue("multipart/form-data; boundary=\(boundary)",forHTTPHeaderField:"Content-Type");request.httpBody=body
        do{let(data,response)=try await URLSession.shared.data(for:request);guard let http=response as? HTTPURLResponse,(200..<300).contains(http.statusCode),let object=try JSONSerialization.jsonObject(with:data) as? [String:Any],let verdict=object["verdict"] as? String,["PASS","FLAG","INSUFFICIENT_EVIDENCE"].contains(verdict) else{throw ServiceError.message("The model returned no valid inspection. Check its connection and try again.")};guard let version=object["model_version"] as? String,!version.lowercased().contains("stub"),object["scan_id"] is String else{throw ServiceError.message("The model returned an unverified or stub result.")};outcome=object;result="\(verdict) · Model \(object["model_version"] as? String ?? "unspecified"). \(object["reason"] as? String ?? "Review the physical evidence before a quality decision.")"}catch{self.error=error.localizedDescription}
    }
}
struct CameraCapture:UIViewControllerRepresentable{
    @Binding var data:Data?;@Environment(\.dismiss) private var dismiss
    func makeUIViewController(context:Context)->UIImagePickerController{let picker=UIImagePickerController();picker.sourceType = .camera;picker.delegate=context.coordinator;return picker}
    func updateUIViewController(_ controller:UIImagePickerController,context:Context){}
    func makeCoordinator()->Coordinator{Coordinator(self)}
    final class Coordinator:NSObject,UIImagePickerControllerDelegate,UINavigationControllerDelegate{let parent:CameraCapture;init(_ parent:CameraCapture){self.parent=parent};func imagePickerController(_ picker:UIImagePickerController,didFinishPickingMediaWithInfo info:[UIImagePickerController.InfoKey:Any]){parent.data=(info[.originalImage] as? UIImage)?.jpegData(compressionQuality:0.9);parent.dismiss()};func imagePickerControllerDidCancel(_ picker:UIImagePickerController){parent.dismiss()}}
}
